import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Observable } from 'rxjs';
import { AppService, AppState } from '../../core/services/app.service';
import { AuthService } from '../../core/services/auth.service';
import { Product } from '../../core/models';
import { Router } from '@angular/router';
import * as JsBarcode from 'jsbarcode';

@Component({
  selector: 'app-inventory',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './inventory.component.html'
})
export class InventoryComponent {
  appState$: Observable<AppState>;
  searchTerm = '';
  categoryFilter = 'all';
  locationFilter = 'all';
  lowStockOnly = false;
  // simple per-card image index (not persisted)
  private imageIndex: Record<string, number> = {};

  constructor(
    private appService: AppService,
    private authService: AuthService,
    private router: Router
  ) {
    this.appState$ = this.appService.appState$;
  }


  getFilteredProducts(appState: AppState): Product[] {
    return appState.products.filter(product => {
      const matchesSearch = product.name.toLowerCase().includes(this.searchTerm.toLowerCase()) ||
                           product.sku.toLowerCase().includes(this.searchTerm.toLowerCase()) ||
                           (product.barcode && product.barcode.includes(this.searchTerm));
      const matchesCategory = this.categoryFilter === 'all' || product.category === this.categoryFilter;
      const matchesLocation = this.locationFilter === 'all' || product.locationId === this.locationFilter;
      const matchesLowStock = !this.lowStockOnly || product.stock <= product.minStock;
      return matchesSearch && matchesCategory && matchesLocation && matchesLowStock;
    });
  }

  // Summary helpers (computed over the filtered list)
  getFilteredCount(appState: AppState): number {
    return this.getFilteredProducts(appState).length;
  }

  getFilteredTotalStock(appState: AppState): number {
    return this.getFilteredProducts(appState).reduce((sum, p) => sum + (p.stock || 0), 0);
  }

  getFilteredInventoryValueRetail(appState: AppState): number {
    return this.getFilteredProducts(appState).reduce((sum, p) => sum + (p.stock || 0) * (p.price || 0), 0);
  }

  getFilteredInventoryValueCost(appState: AppState): number {
    return this.getFilteredProducts(appState).reduce((sum, p) => sum + (p.stock || 0) * (p.cost || 0), 0);
  }

  getFilteredLowStockCount(appState: AppState): number {
    return this.getFilteredProducts(appState).filter(p => p.stock <= p.minStock).length;
  }

  // Barcode/Label printing
  printBarcode(product: Product): void {
    const code = product.barcode || product.sku || product.id;
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    try {
      JsBarcode(svg, code, { format: 'CODE128', width: 2, height: 48, displayValue: false, margin: 0 });
    } catch (e) {
      // Fallback to CODE39 if CODE128 fails
      try { JsBarcode(svg, code, { format: 'CODE39', width: 2, height: 48, displayValue: false, margin: 0 }); } catch {}
    }
    const svgMarkup = new XMLSerializer().serializeToString(svg);

    const name = product.name || '';
    const sku = product.sku || '';
    const size = product.size || '';
    const color = product.color || '';
    const price = `₹${(product.price ?? 0).toFixed(2)}`;
    const location = product.location?.name || '';

    const labelHtml = `
      <div class="label">
        <div class="row top">
          <div class="name">${this.escapeHtml(name)}</div>
          <div class="price">${this.escapeHtml(price)}</div>
        </div>
        <div class="meta">SKU: ${this.escapeHtml(sku)} • ${this.escapeHtml(size)} • ${this.escapeHtml(color)}${location ? ' • ' + this.escapeHtml(location) : ''}</div>
        <div class="barcode">${svgMarkup}</div>
      </div>
    `;

    const win = window.open('', '', 'width=600,height=400');
    if (!win) return;
    win.document.open();
    win.document.write(`
      <html>
        <head>
          <title>Print Label</title>
          <style>
            @page { size: 62mm 30mm; margin: 3mm; }
            body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif; }
            .label { width: 56mm; height: 24mm; display: flex; flex-direction: column; justify-content: space-between; }
            .row.top { display:flex; justify-content: space-between; align-items: baseline; }
            .name { font-size: 10pt; font-weight: 600; max-width: 42mm; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
            .price { font-size: 10pt; font-weight: 700; }
            .meta { font-size: 8pt; color: #444; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
            .barcode svg { width: 100%; height: 18mm; }
            @media print { .label { page-break-after: always; } }
          </style>
        </head>
        <body>${labelHtml}
          <script>
            window.onload = function(){ window.print(); setTimeout(function(){ window.close(); }, 200); };
          <\/script>
        </body>
      </html>
    `);
    win.document.close();
  }

  private escapeHtml(text: string): string {
    const map: any = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' };
    return String(text).replace(/[&<>"']/g, (m) => map[m]);
  }

  getCategoryColor(category: string): string {
    const colors = {
      shirts: 'px-2 py-1 rounded-full text-xs font-medium bg-blue-100 text-blue-800',
      pants: 'px-2 py-1 rounded-full text-xs font-medium bg-indigo-100 text-indigo-800',
      dresses: 'px-2 py-1 rounded-full text-xs font-medium bg-pink-100 text-pink-800',
      jackets: 'px-2 py-1 rounded-full text-xs font-medium bg-gray-100 text-gray-800',
      shoes: 'px-2 py-1 rounded-full text-xs font-medium bg-emerald-100 text-emerald-800',
      accessories: 'px-2 py-1 rounded-full text-xs font-medium bg-purple-100 text-purple-800',
    };
    return colors[category as keyof typeof colors] || 'px-2 py-1 rounded-full text-xs font-medium bg-gray-100 text-gray-800';
  }

  getStockStatusClass(product: Product): string {
    return `flex items-center justify-between p-3 rounded-lg ${
      product.stock <= product.minStock 
        ? 'bg-red-50 border border-red-200' 
        : 'bg-green-50 border border-green-200'
    }`;
  }

  getStockTextClass(product: Product): string {
    return `text-lg font-bold ${
      product.stock <= product.minStock ? 'text-red-600' : 'text-green-600'
    }`;
  }

  getStockBadgeClass(product: Product): string {
    return `px-2 py-0.5 rounded text-xs font-semibold ${
      product.stock <= product.minStock
        ? 'text-red-700 bg-red-100 border border-red-200'
        : 'text-green-700 bg-green-100 border border-green-200'
    }`;
  }

  formatPrice(value: number): string {
    return `₹${value.toFixed(2)}`;
  }

  canEdit(): boolean {
    const user = this.authService.getCurrentUser();
    return user?.role === 'admin' || user?.role === 'warehouse';
  }

  onEdit(product: Product): void {
    if (!this.canEdit()) return;
    this.router.navigate(['/add-product'], { queryParams: { id: product.id } });
  }

  showLowStock(): void {
    this.lowStockOnly = true;
  }

  clearLowStockFilter(): void {
    this.lowStockOnly = false;
  }

  // Print all filtered products barcodes (first image index not relevant)
  printFilteredBarcodes(): void {
    const state = this.appService.appStateBehaviorSubject.value;
    const products = this.getFilteredProducts(state);
    products.forEach(p => this.printBarcode(p));
  }

  // image helpers for card (optional nav)
  getImage(product: Product): string | undefined {
    const idx = this.imageIndex[product.id] || 0;
    return product.imageUrls && product.imageUrls[idx] ? product.imageUrls[idx] : product.imageUrls?.[0];
  }

  nextImage(product: Product): void {
    if (!product.imageUrls || product.imageUrls.length <= 1) return;
    const current = this.imageIndex[product.id] || 0;
    this.imageIndex[product.id] = (current + 1) % product.imageUrls.length;
  }

  prevImage(product: Product): void {
    if (!product.imageUrls || product.imageUrls.length <= 1) return;
    const current = this.imageIndex[product.id] || 0;
    this.imageIndex[product.id] = (current - 1 + product.imageUrls.length) % product.imageUrls.length;
  }

  // Template guards/helpers for strict mode
  hasAnyImages(product: Product): boolean {
    return !!(product.imageUrls && product.imageUrls.length > 0);
  }

  hasMultipleImages(product: Product): boolean {
    return !!(product.imageUrls && product.imageUrls.length > 1);
  }

  imageCount(product: Product): number {
    return product.imageUrls ? product.imageUrls.length : 0;
  }

  currentImageNo(product: Product): number {
    const count = this.imageCount(product);
    const idx = this.imageIndex[product.id] || 0;
    return Math.min(idx + 1, count || 1);
  }
}
<div class="max-w-7xl mx-auto px-4 space-y-6" *ngIf="appState$ | async as appState">
  <!-- Search and Filter -->
  <div class="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100">
    <div class="space-y-4">
      <!-- Search Bar -->
      <div class="relative">
        <div class="pointer-events-none absolute inset-y-0 left-3 flex items-center">
          <svg class="h-4 w-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <circle cx="11" cy="11" r="7" stroke-width="1.6"></circle>
            <path stroke-linecap="round" stroke-width="1.6" d="M20 20l-3.5-3.5"></path>
          </svg>
        </div>
        <input
          type="text"
          [(ngModel)]="searchTerm"
          placeholder="Search products by name, SKU, or barcode..."
          class="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
        />
      </div>

      <!-- Filters -->
      <div class="flex flex-col sm:flex-row gap-3">
        <select
          [(ngModel)]="categoryFilter"
          class="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
        >
          <option value="all">All Categories</option>
          <option value="shirts">Shirts</option>
          <option value="pants">Pants</option>
          <option value="dresses">Dresses</option>
          <option value="jackets">Jackets</option>
          <option value="shoes">Shoes</option>
          <option value="accessories">Accessories</option>
        </select>
        <select
          [(ngModel)]="locationFilter"
          class="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
        >
          <option value="all">All Locations</option>
          <option *ngFor="let location of appState.locations" [value]="location.id">
            {{ location.name }} ({{ location.type }})
          </option>
        </select>
      </div>
    </div>
  </div>

  <!-- Summary (single row, scrollable on small screens) -->
  <div class="overflow-x-auto">
    <div class="flex flex-nowrap gap-3 md:gap-4">
      <div class="min-w-[220px] bg-white rounded-xl border border-gray-200 p-4 shadow-sm flex items-center justify-between">
        <div>
        <div class="text-sm text-gray-500">Products</div>
        <div class="mt-1 text-2xl font-semibold text-gray-900">{{ getFilteredCount(appState) | number }}</div>
        </div>
        <svg class="h-6 w-6 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"/></svg>
      </div>
      <div class="min-w-[220px] bg-white rounded-xl border border-gray-200 p-4 shadow-sm flex items-center justify-between">
        <div>
        <div class="text-sm text-gray-500">Total Quantity</div>
        <div class="mt-1 text-2xl font-semibold text-gray-900">{{ getFilteredTotalStock(appState) | number }}</div>
        </div>
        <svg class="h-6 w-6 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 3h18M3 12h18M3 21h18"/></svg>
      </div>
      <div class="min-w-[220px] bg-white rounded-xl border border-gray-200 p-4 shadow-sm flex items-center justify-between">
        <div>
        <div class="text-sm text-gray-500">Inventory Value (Retail)</div>
        <div class="mt-1 text-2xl font-semibold text-green-700">₹{{ getFilteredInventoryValueRetail(appState) | number:'1.2-2' }}</div>
        </div>
      </div>
      <div class="min-w-[220px] bg-white rounded-xl border border-gray-200 p-4 shadow-sm flex items-center justify-between">
        <div>
        <div class="text-sm text-gray-500">Inventory Value (Cost)</div>
        <div class="mt-1 text-2xl font-semibold text-emerald-700 text-green-700" >₹{{ getFilteredInventoryValueCost(appState) | number:'1.2-2' }}</div>
        </div>
      </div>
      <div class="min-w-[220px] bg-white rounded-xl border border-gray-200 p-4 shadow-sm flex items-center justify-between cursor-pointer hover:border-amber-300" (click)="showLowStock()" role="button" tabindex="0">
        <div>
          <div class="text-sm text-gray-500">Low Stock Items</div>
          <div class="mt-1 text-2xl font-semibold" [class]="getFilteredLowStockCount(appState) > 0 ? 'text-amber-600' : 'text-gray-900'">
            {{ getFilteredLowStockCount(appState) | number }}
          </div>
        </div>
        <svg class="h-6 w-6 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01M5.07 19h13.86c1.54 0 2.5-1.67 1.73-3L13.73 5c-.77-1.33-2.7-1.33-3.46 0L3.34 16c-.77 1.33.19 3 1.73 3z"/></svg>
      </div>
    </div>
  </div>

  <!-- Active low stock filter banner -->
  <div *ngIf="lowStockOnly" class="flex items-center gap-2 text-sm bg-amber-50 border border-amber-200 text-amber-800 px-3 py-2 rounded-lg w-fit">
    <svg class="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01M5.07 19h13.86c1.54 0 2.5-1.67 1.73-3L13.73 5c-.77-1.33-2.7-1.33-3.46 0L3.34 16c-.77 1.33.19 3 1.73 3z"/></svg>
    <span>Showing low stock items only</span>
    <button (click)="clearLowStockFilter()" class="ml-2 underline hover:no-underline">Clear</button>
  </div>

  <!-- Toolbar: filter + barcodes + print -->
  <div class="bg-white rounded-xl shadow-sm border border-gray-100 p-3 flex flex-wrap items-center gap-3">
    <div class="relative flex-1 min-w-[240px]">
      <div class="pointer-events-none absolute inset-y-0 left-3 flex items-center">
        <svg class="h-4 w-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle cx="11" cy="11" r="7" stroke-width="1.6"/><path stroke-linecap="round" stroke-width="1.6" d="M20 20l-3.5-3.5"/></svg>
      </div>
      <input type="text" [(ngModel)]="searchTerm" placeholder="Search products by name, SKU, or barcode..."
             class="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
    </div>
    <select [(ngModel)]="categoryFilter" class="px-3 py-2 border border-gray-300 rounded-lg">
      <option value="all">All Categories</option>
      <option value="shirts">Shirts</option>
      <option value="pants">Pants</option>
      <option value="dresses">Dresses</option>
      <option value="jackets">Jackets</option>
      <option value="shoes">Shoes</option>
      <option value="accessories">Accessories</option>
    </select>
    <select [(ngModel)]="locationFilter" class="px-3 py-2 border border-gray-300 rounded-lg">
      <option value="all">All Locations</option>
      <option *ngFor="let location of appState.locations" [value]="location.id">{{ location.name }} ({{ location.type }})</option>
    </select>
    <button (click)="printFilteredBarcodes()" class="px-4 py-2 rounded-lg bg-emerald-600 text-white hover:bg-emerald-700">Print</button>
  </div>

  <!-- Card Grid -->
  <div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
    <div *ngFor="let product of getFilteredProducts(appState)" class="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
      <!-- Image carousel (simple) -->
      <div class="relative h-44 bg-gray-100">
        <img *ngIf="hasAnyImages(product); else noImg" [src]="getImage(product)" [alt]="product.name" class="w-full h-full object-cover" />
        <ng-template #noImg>
          <div class="w-full h-full flex items-center justify-center text-gray-400">
            <svg class="h-8 w-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
          </div>
        </ng-template>
        <div *ngIf="hasMultipleImages(product)" class="absolute inset-y-0 left-0 flex items-center">
          <button (click)="prevImage(product)" class="m-2 h-8 w-8 rounded-full bg-white/80 hover:bg-white shadow flex items-center justify-center">‹</button>
        </div>
        <div *ngIf="hasMultipleImages(product)" class="absolute inset-y-0 right-0 flex items-center">
          <button (click)="nextImage(product)" class="m-2 h-8 w-8 rounded-full bg-white/80 hover:bg-white shadow flex items-center justify-center">›</button>
        </div>
        <div class="absolute top-2 left-2 text-xs px-2 py-0.5 rounded-full bg-black/60 text-white" *ngIf="hasAnyImages(product)">{{ currentImageNo(product) }} / {{ imageCount(product) }}</div>
        <div class="absolute top-2 right-2 flex gap-1" *ngIf="canEdit()">
          <button (click)="printBarcode(product)" title="Print" class="p-2 bg-white/90 rounded-lg hover:bg-white shadow">
            <svg class="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 9V2h12v7M6 18H5a2 2 0 01-2-2v-5a2 2 0 012-2h14a2 2 0 012 2v5a2 2 0 01-2 2h-1M9 14h6m-9 4h12v4H6v-4z"/></svg>
          </button>
          <button (click)="onEdit(product)" title="Edit" class="p-2 bg-white/90 rounded-lg hover:bg-white shadow">
            <svg class="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
          </button>
        </div>
      </div>
      <!-- Body -->
      <div class="p-4">
        <div class="flex items-center justify-between">
          <div class="text-xs">
            <span [class]="getCategoryColor(product.category)">{{ product.category }}</span>
            <span class="ml-2 text-gray-500">{{ product.sku }}</span>
          </div>
        </div>
        <h3 class="mt-2 text-base font-semibold text-gray-900">{{ product.name }}</h3>
        <p class="text-sm text-gray-600 line-clamp-2">{{ product.description }}</p>

        <div class="mt-3 grid grid-cols-2 gap-2 text-sm">
          <div><span class="text-gray-500">Size:</span> <span class="font-medium">{{ product.size }}</span></div>
          <div><span class="text-gray-500">Color:</span> <span class="font-medium">{{ product.color }}</span></div>
          <div class="col-span-2"><span class="text-gray-500">Location:</span> <span class="font-medium">{{ product.location.name }}</span></div>
          <div><span class="text-gray-500">Price:</span> <span class="font-semibold text-green-600">₹{{ product.price.toFixed(2) }}</span></div>
          <div><span class="text-gray-500">Wholesale (100+):</span> <span class="font-semibold text-green-600">₹{{ product.wholesalePrice.toFixed(2) }}</span></div>
        </div>

        <div class="mt-3" [class]="getStockStatusClass(product)">
          <span class="text-sm font-medium text-gray-700">Stock:</span>
          <div class="text-right">
            <span [class]="getStockTextClass(product)">{{ product.stock }}</span>
            <span class="text-xs text-gray-500 ml-1">/ {{ product.minStock }} min</span>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- No Results -->
  <div *ngIf="getFilteredProducts(appState).length === 0" class="text-center py-12">
    <svg class="h-12 w-12 text-gray-400 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path>
    </svg>
    <p class="text-gray-500">No products found matching your criteria.</p>
  </div>
</div>
